    if (e.key === 'ArrowUp') {
      e.preventDefault();
      increment();
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      decrement();
    } else if (e.key === 'Enter') {
      inputRef.current?.blur();
    }
  };

  const handleWheel = (e: WheelEvent<HTMLInputElement>) => {
    if (!allowMouseWheel || disabled || !isFocused) return;
    e.preventDefault();
    if (e.deltaY < 0) {
      increment();
    } else {
      decrement();
    }
  };

  return (
    <div className={className}>
      {label && (
        <label className="block text-sm font-medium text-surface-200 mb-1.5">
          {label}
        </label>
      )}

      <div className="flex items-center">
        {showButtons && (
          <button
            type="button"
            onClick={decrement}
            disabled={disabled || Number(localValue) <= min}
            className={`
              ${sizeStyles[size].button}
              flex items-center justify-center
              bg-surface-700 hover:bg-surface-600
              border border-surface-600 border-r-0
              rounded-l-lg
              text-surface-300 hover:text-surface-100
              transition-colors duration-150
              disabled:opacity-50 disabled:cursor-not-allowed
            `}
            aria-label="Decrease value"
          >
            <Icon name="minus" size="sm" />
          </button>
        )}

        <div className="relative flex-1">
          <input
            ref={inputRef}
            type="text"
            inputMode="decimal"
            value={localValue}
            onChange={handleInputChange}
            onBlur={handleBlur}
            onFocus={handleFocus}
            onKeyDown={handleKeyDown}
            onWheel={handleWheel}
            disabled={disabled}
            className={`
              ${sizeStyles[size].input}
              w-full
              bg-surface-800 text-surface-100
              border border-surface-600
              ${showButtons ? 'rounded-none' : 'rounded-lg'}
              text-center font-mono
              focus:outline-none focus:border-primary-500 focus:ring-1 focus:ring-primary-500/30
              disabled:opacity-50 disabled:cursor-not-allowed
              transition-colors duration-150
              ${unit ? 'pr-8' : ''}
            `}
          />
          {unit && (
            <span className="absolute right-3 top-1/2 -translate-y-1/2 text-surface-400 text-sm pointer-events-none">
              {unit}
            </span>
          )}
        </div>

        {showButtons && (
          <button
            type="button"
            onClick={increment}
            disabled={disabled || Number(localValue) >= max}
            className={`
              ${sizeStyles[size].button}
              flex items-center justify-center
              bg-surface-700 hover:bg-surface-600
              border border-surface-600 border-l-0
              rounded-r-lg
              text-surface-300 hover:text-surface-100
              transition-colors duration-150
              disabled:opacity-50 disabled:cursor-not-allowed
            `}
            aria-label="Increase value"
          >
            <Icon name="plus" size="sm" />
          </button>
        )}
      </div>

      {min !== -Infinity && max !== Infinity && (
        <div className="mt-1 text-xs text-surface-500 text-center">
          {min} - {max}
        </div>
      )}
    </div>
  );
}

