        {children}
      </main>

      {/* Recording controls */}
      <div className="flex items-center justify-center gap-3 py-4 px-4 bg-surface-800 border-t border-surface-700">
        {/* Duration display */}
        <div className="flex items-center gap-2 min-w-[100px]">
