                <Button
                  variant="primary"
                  size="lg"
                  onClick={onStop}
                  leftIcon={<Icon name="stop" />}
                >
                  Stop
                </Button>
              </Tooltip>
              <Tooltip content="Discard Recording" position="top">
                <Button
                  variant="ghost"
                  size="lg"
                  onClick={onDiscard}
                  leftIcon={<Icon name="trash" />}
                >
                  Discard
